-- Recorded processing time is separate source data, never regenerated by replay.
-- Ten-second UTC buckets have explicit origin and half-open membership.
SELECT g.bidder,g.bid_count,g.starttime,g.starttime+INTERVAL '10 seconds' AS endtime
FROM (
    SELECT b.bidder,COUNT(*) AS bid_count,
           date_bin(INTERVAL '10 seconds',b.processing_time,
                    TIMESTAMPTZ '2000-01-01 00:00:00+00') AS starttime
    FROM nexmark.bid b
    GROUP BY b.bidder,date_bin(INTERVAL '10 seconds',b.processing_time,
                              TIMESTAMPTZ '2000-01-01 00:00:00+00')
) g;
